cd /workspace && python3 -c "
from fractions import Fraction as F
# brute force the endpoint-cycle model to confirm interpretation
G=((0,0,1),(1,1,2),(1,1,2))
INV=(2,1,0)
paths=[((41,67,109),2),((67,109,41),3),((109,41,67),5)]
core=[(41,67),(41,109),(67,109)]
idx={l:i for i,l in enumerate(core)}
occ={i:[] for i in range(3)}
for p,c in paths:
    n=len(p)
    for i in range(n-1):
        u,v=p[i],p[i+1]
        if u<v:
            key=(u,v); j=i; o=p
        else:
            key=(v,u); j=n-2-i; o=p[::-1]
        e=idx[key]
        if j==0: L=(0,0)
        else:
            x=o[j-1]; pk=(x,o[j]) if x<o[j] else (o[j],x)
            L=(1,idx[pk],0 if x<o[j] else 1)
        if j+2>=n: R=(0,2)
        else:
            y=o[j+2]; sk=(o[j+1],y) if o[j+1]<y else (y,o[j+1])
            R=(1,idx[sk],0 if o[j+1]<y else 1)
        occ[e].append((c,L,R))
def res(spec,st):
    if spec[0]==0: return spec[1]
    s=st[spec[1]]
    return INV[s] if spec[2] else s
import itertools
Z=0; num=[[0,0,0] for _ in range(3)]
for assign in itertools.product(range(3),repeat=3):
    st=list(assign); W=1
    for e in range(3):
        phi=[0,0,0]
        for (c,L,R) in occ[e]:
            phi[G[res(L,st)][res(R,st)]]+=c
        W*=phi[st[e]]
    Z+=W
    for e in range(3): num[e][st[e]]+=W
print('Z',Z)
for e in range(3):
    print(core[e], [float(F(n,Z)) for n in num[e]], [F(n,Z) for n in num[e]])
"

