mkdir -p /workspace/submission && cat > /workspace/submission/main.py <<'PYEOF'
#!/usr/bin/env python3
"""Offline BGP relationship inference and route leak scoring service.

Implements PROTOCOL.md (core routing inference service, version 1, revision 1):
AS path normalisation, simultaneous peripheral-link peeling, exact joint
inference over ternary core-link relationship variables and triple/full path
legitimacy scoring.

The program reads one JSON document from stdin and writes one JSON document to
stdout.  It uses the standard library only and keeps no state between runs.
"""

import json
import re
import sys
from fractions import Fraction

# --------------------------------------------------------------------------
# limits and constants
# --------------------------------------------------------------------------
MAX_INPUT_BYTES = 4194304
MAX_IXPS = 1024
MAX_RIB_RECORDS = 2000
MAX_PRIORS = 2000
MAX_DECLARED = 2000
MAX_QUERIES = 512
MAX_PATH_LEN = 64
MAX_RIB_PATH_TOTAL = 40000
MAX_COUNT = 1000000
MAX_WEIGHT = 1000000
MAX_THRESHOLD = 1000000
AS_MIN = 1
AS_MAX = 4294967295
MAX_WIDTH = 4

TOP_KEYS = frozenset(('version', 'ixps', 'rib', 'priors', 'declared',
                      'order', 'queries'))
TYPE_NAMES = ('c2p', 'p2p', 'p2c')
TYPE_INDEX = {name: i for i, name in enumerate(TYPE_NAMES)}
INVERSE = (2, 1, 0)
# G_TABLE[L][R] = preferred centre type for context (L, R).
G_TABLE = (
    (0, 0, 1),   # L = c2p
    (1, 1, 2),   # L = p2p
    (1, 1, 2),   # L = p2c
)
ID_RE = re.compile(r'\A[A-Za-z0-9_.-]{1,64}\Z')
UNIFORM = (Fraction(1, 3), Fraction(1, 3), Fraction(1, 3))


class Invalid(Exception):
    """The request is outside the documented schema or bounds."""


# --------------------------------------------------------------------------
# document parsing
# --------------------------------------------------------------------------
def _object_pairs(pairs):
    result = {}
    for key, value in pairs:
        if key in result:
            raise Invalid('duplicate key')
        result[key] = value
    return result


def _reject_constant(name):
    raise Invalid('non finite number')


def parse_document(raw):
    if len(raw) > MAX_INPUT_BYTES:
        raise Invalid('input too large')
    try:
        text = raw.decode('utf-8')
    except UnicodeDecodeError:
        raise Invalid('invalid utf-8')
    try:
        return json.loads(text, object_pairs_hook=_object_pairs,
                          parse_constant=_reject_constant)
    except Invalid:
        raise
    except Exception:
        raise Invalid('invalid json')


# --------------------------------------------------------------------------
# schema validation helpers
# --------------------------------------------------------------------------
def _is_int(value):
    return type(value) is int


def _asn(value):
    if not _is_int(value) or value < AS_MIN or value > AS_MAX:
        raise Invalid('bad asn')
    return value


def _link_ends(value):
    if not isinstance(value, list) or len(value) != 2:
        raise Invalid('bad link')
    u = _asn(value[0])
    v = _asn(value[1])
    if u == v:
        raise Invalid('self link')
    return u, v


def validate_request(data):
    """Validate the whole request; returns the parsed pieces."""
    if not isinstance(data, dict) or frozenset(data.keys()) != TOP_KEYS:
        raise Invalid('bad top level object')
    if not _is_int(data['version']) or data['version'] != 1:
        raise Invalid('bad version')

    ixp_list = data['ixps']
    if not isinstance(ixp_list, list) or len(ixp_list) > MAX_IXPS:
        raise Invalid('bad ixps')
    ixps = set()
    for asn in ixp_list:
        _asn(asn)
        if asn in ixps:
            raise Invalid('duplicate ixp')
        ixps.add(asn)

    rib = data['rib']
    if not isinstance(rib, list) or len(rib) > MAX_RIB_RECORDS:
        raise Invalid('bad rib')
    rib_records = []
    total_len = 0
    for record in rib:
        if not isinstance(record, dict) or \
                frozenset(record.keys()) != frozenset(('path', 'count')):
            raise Invalid('bad rib record')
        path = record['path']
        count = record['count']
        if not isinstance(path, list) or len(path) > MAX_PATH_LEN:
            raise Invalid('bad rib path')
        for asn in path:
            _asn(asn)
        if not _is_int(count) or count < 1 or count > MAX_COUNT:
            raise Invalid('bad rib count')
        total_len += len(path)
        rib_records.append((tuple(path), count))
    if total_len > MAX_RIB_PATH_TOTAL:
        raise Invalid('rib path budget exceeded')

    priors = {}
    prior_list = data['priors']
    if not isinstance(prior_list, list) or len(prior_list) > MAX_PRIORS:
        raise Invalid('bad priors')
    for record in prior_list:
        if not isinstance(record, dict) or \
                frozenset(record.keys()) != frozenset(('link', 'weights')):
            raise Invalid('bad prior record')
        u, v = _link_ends(record['link'])
        weights = record['weights']
        if not isinstance(weights, list) or len(weights) != 3:
            raise Invalid('bad weights')
        total = 0
        for weight in weights:
            if not _is_int(weight) or weight < 0 or weight > MAX_WEIGHT:
                raise Invalid('bad weight')
            total += weight
        if total <= 0:
            raise Invalid('weights sum to zero')
        key = (u, v) if u < v else (v, u)
        if key in priors:
            raise Invalid('duplicate prior')
        probs = [Fraction(weight, total) for weight in weights]
        if u > v:
            probs = [probs[2], probs[1], probs[0]]
        priors[key] = tuple(probs)

    declared = {}
    declared_list = data['declared']
    if not isinstance(declared_list, list) or len(declared_list) > MAX_DECLARED:
        raise Invalid('bad declared')
    for record in declared_list:
        if not isinstance(record, dict) or \
                frozenset(record.keys()) != frozenset(('link', 'rel')):
            raise Invalid('bad declared record')
        u, v = _link_ends(record['link'])
        rel = record['rel']
        if not isinstance(rel, str) or rel not in TYPE_INDEX:
            raise Invalid('bad relationship')
        key = (u, v) if u < v else (v, u)
        if key in declared:
            raise Invalid('duplicate declaration')
        onehot = [0, 0, 0]
        onehot[TYPE_INDEX[rel]] = 1
        if u > v:
            onehot = onehot[2::-1]
        declared[key] = tuple(onehot)

    order = data['order']
    if not isinstance(order, list):
        raise Invalid('bad order')
    order_links = []
    for item in order:
        if not isinstance(item, list) or len(item) != 2:
            raise Invalid('bad order item')
        u = _asn(item[0])
        v = _asn(item[1])
        if u >= v:
            raise Invalid('order item not canonical')
        order_links.append((u, v))

    queries = data['queries']
    if not isinstance(queries, list) or len(queries) > MAX_QUERIES:
        raise Invalid('bad queries')
    query_records = []
    seen_ids = set()
    for record in queries:
        if not isinstance(record, dict) or \
                frozenset(record.keys()) != frozenset(('id', 'path', 'threshold')):
            raise Invalid('bad query record')
        qid = record['id']
        if not isinstance(qid, str) or not ID_RE.match(qid):
            raise Invalid('bad query id')
        if qid in seen_ids:
            raise Invalid('duplicate query id')
        seen_ids.add(qid)
        path = record['path']
        if not isinstance(path, list) or len(path) > MAX_PATH_LEN:
            raise Invalid('bad query path')
        for asn in path:
            _asn(asn)
        threshold = record['threshold']
        if not isinstance(threshold, list) or len(threshold) != 2:
            raise Invalid('bad threshold')
        num, den = threshold
        if not _is_int(num) or not _is_int(den):
            raise Invalid('bad threshold')
        if den < 1 or num < 0 or num > den or den > MAX_THRESHOLD:
            raise Invalid('bad threshold')
        query_records.append((qid, tuple(path), num, den))

    return ixps, rib_records, priors, declared, order_links, query_records


# --------------------------------------------------------------------------
# path normalisation and aggregation
# --------------------------------------------------------------------------
def normalise(path, ixps):
    """Remove IXP ASNs, then collapse adjacent duplicate runs."""
    result = []
    for asn in path:
        if asn in ixps:
            continue
        if result and result[-1] == asn:
            continue
        result.append(asn)
    return result


def aggregate_rib(rib_records, ixps):
    """Normalised, loop free, non trivial directed paths with summed counts."""
    aggregated = {}
    for path, count in rib_records:
        cleaned = normalise(path, ixps)
        if len(cleaned) < 2:
            continue
        if len(set(cleaned)) != len(cleaned):
            continue
        key = tuple(cleaned)
        aggregated[key] = aggregated.get(key, 0) + count
    return aggregated


def path_links(path):
    links = set()
    for i in range(len(path) - 1):
        u, v = path[i], path[i + 1]
        links.add((u, v) if u < v else (v, u))
    return links


def peel(paths):
    """Simultaneous peripheral peeling.

    Returns (core_paths, rounds) where rounds maps a removed link to the
    round in which it was peeled.
    """
    rounds = {}
    current = dict(paths)
    round_no = 0
    while current:
        # count, per link, the paths containing it and how often each of the
        # two fixed endpoints is a path endpoint in those paths.
        stats = {}
        for path in current:
            first, last = path[0], path[-1]
            for i in range(len(path) - 1):
                u, v = path[i], path[i + 1]
                key = (u, v) if u < v else (v, u)
                entry = stats.get(key)
                if entry is None:
                    entry = stats[key] = [0, 0, 0]
                entry[0] += 1
                if key[0] == first or key[0] == last:
                    entry[1] += 1
                if key[1] == first or key[1] == last:
                    entry[2] += 1
        marked = set()
        for key, entry in stats.items():
            if entry[1] == entry[0] or entry[2] == entry[0]:
                marked.add(key)
        if not marked:
            break
        round_no += 1
        for key in marked:
            rounds[key] = round_no
        trimmed_paths = {}
        for path, count in current.items():
            first_link = (path[0], path[1])
            if first_link[0] > first_link[1]:
                first_link = (first_link[1], first_link[0])
            last_link = (path[-2], path[-1])
            if last_link[0] > last_link[1]:
                last_link = (last_link[1], last_link[0])
            start = 1 if first_link in marked else 0
            stop = len(path) - (1 if last_link in marked else 0)
            trimmed = path[start:stop]
            if len(trimmed) >= 2:
                trimmed_paths[trimmed] = trimmed_paths.get(trimmed, 0) + count
        current = trimmed_paths
    return current, rounds


# --------------------------------------------------------------------------
# exact core model
# --------------------------------------------------------------------------
def collect_occurrences(core_paths, core_index):
    """One entry per link occurrence: (count, left spec, right spec).

    A spec is (0, type) for a constant context type or (1, variable, flipped)
    for a context given by another core variable, possibly reversed.
    """
    occurrences = {index: [] for index in core_index.values()}
    for path, count in core_paths.items():
        size = len(path)
        for position in range(size - 1):
            u, v = path[position], path[position + 1]
            if u < v:
                key = (u, v)
                offset = position
                oriented = path
            else:
                key = (v, u)
                offset = size - 2 - position
                oriented = path[::-1]
            edge = core_index[key]
            if offset == 0:
                left = (0, 0)                      # missing predecessor: c2p
            else:
                x = oriented[offset - 1]
                y = oriented[offset]
                prev = (x, y) if x < y else (y, x)
                left = (1, core_index[prev], 0 if x < y else 1)
            if offset + 2 >= size:
                right = (0, 2)                     # missing successor: p2c
            else:
                y = oriented[offset + 1]
                z = oriented[offset + 2]
                nxt = (y, z) if y < z else (z, y)
                right = (1, core_index[nxt], 0 if y < z else 1)
            occurrences[edge].append((count, left, right))
    return occurrences


def build_scopes(core_index, occurrences):
    """Scope of every core variable: itself plus its context variables."""
    scopes = {}
    for edge, items in occurrences.items():
        scope = set((edge,))
        for _count, left, right in items:
            for spec in (left, right):
                if spec[0] == 1:
                    scope.add(spec[1])
        scopes[edge] = sorted(scope)
    return scopes


def check_order(core, order_links, scopes):
    """Validate the elimination order and the promised width."""
    if len(order_links) != len(core):
        raise Invalid('order length')
    seen = set()
    for link in order_links:
        if link in seen:
            raise Invalid('duplicate order entry')
        seen.add(link)
    if seen != set(core):
        raise Invalid('order is not a permutation of the core links')
    index = {link: position for position, link in enumerate(core)}
    adjacency = {position: set() for position in range(len(core))}
    for scope in scopes.values():
        for a in scope:
            for b in scope:
                if a != b:
                    adjacency[a].add(b)
    for link in order_links:
        node = index[link]
        neighbours = adjacency[node]
        if len(neighbours) > MAX_WIDTH:
            raise Invalid('width promise violated')
        group = list(neighbours)
        for a in group:
            for b in group:
                if a != b:
                    adjacency[a].add(b)
                    adjacency[b].add(a)
        del adjacency[node]
    return [index[link] for link in order_links]


def expand_to(src_vars, src_table, dst_vars):
    """Broadcast a factor table onto the variable set dst_vars."""
    position = {var: i for i, var in enumerate(src_vars)}
    source = [0]
    for var in dst_vars:
        slot = position.get(var)
        if slot is None:
            grown = []
            for value in source:
                grown.append(value)
                grown.append(value)
                grown.append(value)
        else:
            stride = 3 ** (len(src_vars) - 1 - slot)
            grown = []
            for value in source:
                base = value - (value // stride % 3) * stride
                grown.append(base)
                grown.append(base + stride)
                grown.append(base + 2 * stride)
        source = grown
    return [src_table[value] for value in source]


def multiply(first, second):
    """Product of two factors over the union of their variables."""
    vars_a, table_a = first
    vars_b, table_b = second
    if vars_a == vars_b:
        return (vars_a, [x * y for x, y in zip(table_a, table_b)])
    union = tuple(sorted(set(vars_a) | set(vars_b)))
    wide = expand_to(vars_a, table_a, union)
    narrow = expand_to(vars_b, table_b, union)
    return (union, [x * y for x, y in zip(wide, narrow)])


def sum_out(factor, variable):
    """Marginalise one variable out of a factor."""
    variables, table = factor
    size = len(variables)
    slot = variables.index(variable)
    stride = 3 ** (size - 1 - slot)
    powers = [1] * (size + 1)
    for i in range(size):
        powers[i + 1] = powers[i] * 3
    result = [0] * powers[size - 1]
    for old in range(powers[size]):
        digit = (old // stride) % 3
        base = old - digit * stride
        new = (base // (3 * stride)) * stride + (base % stride)
        result[new] += table[old]
    keep = variables[:slot] + variables[slot + 1:]
    return (keep, result)


def eliminate(factors, order, skip=None):
    """Bucket elimination; returns the factors left in the pool."""
    pool = list(factors)
    for variable in order:
        if variable == skip:
            continue
        bucket = []
        rest = []
        for factor in pool:
            if variable in factor[0]:
                bucket.append(factor)
            else:
                rest.append(factor)
        if not bucket:
            continue
        combined = bucket[0]
        for factor in bucket[1:]:
            combined = multiply(combined, factor)
        rest.append(sum_out(combined, variable))
        pool = rest
    return pool


def build_factor(scope, items):
    """Build the factor phi_e over its scope."""
    size = len(scope)
    edge = None
    for position, var in enumerate(scope):
        if var in items[0][0] if False else False:
            pass
    edge = scope[0]
    # the centre variable is the one whose occurrences we collected
    return scope, items


def factor_table(scope, edge, items):
    """Tabulated phi_e over the variables of its scope."""
    size = len(scope)
    context = [var for var in scope if var != edge]
    groups = {}
    for count, left, right in items:
        key = (left, right)
        groups[key] = groups.get(key, 0) + count
    context_pos = {var: i for i, var in enumerate(context)}
    slot = scope.index(edge)
    edge_power = 3 ** (size - 1 - slot)
    powers = []
    running = 1
    for _ in range(size):
        powers.append(running)
        running *= 3
    table = [0] * powers[size]
    context_size = len(context)
    for assignment in range(powers[context_size]):
        states = []
        value = assignment
        for _ in range(context_size):
            states.append(value % 3)
            value //= 3
        # index contribution of the context variables (context[0] is most
        # significant within the context block)
        base = 0
        for position, var in enumerate(context):
            base += states[position] * powers[size - 2 - position]
        for left, right in groups:
            left_type = _resolve(left, states, context_pos)
            right_type = _resolve(right, states, context_pos)
            centre = G_TABLE[left_type][right_type]
            table[base + centre * edge_power] += groups[(left, right)]
    return (tuple(scope), table)


def _resolve(spec, states, context_pos):
    if spec[0] == 0:
        return spec[1]
    state = states[context_pos[spec[1]]]
    return INVERSE[state] if spec[2] else state


def components(scopes, order):
    """Split the core variables into independent components."""
    parent = {}

    def find(node):
        while parent[node] != node:
            parent[node] = parent[parent[node]]
            node = parent[node]
        return node

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[ra] = rb

    for var in parent:
        pass
    for scope in scopes.values():
        for var in scope:
            if var not in parent:
                parent[var] = var
        first = scope[0]
        for var in scope[1:]:
            union(first, var)
    groups = {}
    for var in parent:
        groups.setdefault(find(var), []).append(var)
    result = []
    for members in groups.values():
        members.sort()
        local_order = [v for v in order if v in set(members)]
        result.append((members, local_order))
    return result


def infer_marginals(core, scopes, occurrences, order):
    """Exact marginals of every core variable and the partition function."""
    factors = []
    for edge in sorted(occurrences):
        factors.append(factor_table(scopes[edge], edge, occurrences[edge]))
    numerators = {}
    partition = 1
    zero_partition = False
    for members, local_order in components(scopes, order):
        member_set = set(members)
        local_factors = [f for f in factors if set(f[0]) <= member_set]
        local_partition = None
        for variable in members:
            pool = eliminate(local_factors, local_order, skip=variable)
            constant = 1
            values = [1, 1, 1]
            for variables, table in pool:
                if not variables:
                    constant *= table[0]
                else:
                    for state in range(3):
                        values[state] *= table[state]
            row = [constant * values[state] for state in range(3)]
            numerators[variable] = row
            total = row[0] + row[1] + row[2]
            if local_partition is None:
                local_partition = total
        if local_partition == 0:
            zero_partition = True
        partition *= local_partition if local_partition is not None else 1
    if zero_partition or partition == 0:
        return None, 0
    marginals = {}
    for edge, row in numerators.items():
        marginals[edge] = tuple(Fraction(value, partition) for value in row)
    return marginals, partition


# --------------------------------------------------------------------------
# scoring
# --------------------------------------------------------------------------
def link_probability(u, v, declared, marginals, priors):
    """Probability vector for the directed link u -> v."""
    key = (u, v) if u < v else (v, u)
    vector = declared.get(key)
    if vector is None:
        vector = marginals.get(key)
    if vector is None:
        vector = priors.get(key)
    if vector is None:
        vector = UNIFORM
    if u < v:
        return vector
    return (vector[2], vector[1], vector[0])


def score_query(path, threshold, declared, marginals, priors):
    """Legitimacy score, full weight, witness and leak decision."""
    vectors = []
    for i in range(len(path) - 1):
        vectors.append(link_probability(path[i], path[i + 1], declared,
                                        marginals, priors))
    if len(path) < 3:
        return Fraction(1), Fraction(1), None, False
    best = None
    witness = None
    for i in range(len(vectors) - 1):
        up = vectors[i][0]
        down = vectors[i + 1][2]
        value = up + down - up * down
        if best is None or value < best:
            best = value
            witness = i
    # sum of all type sequences c2p* p2c* or c2p* p2p p2c*
    only_up = Fraction(1)
    down_run = Fraction(0)
    peer_run = Fraction(0)
    for vector in vectors:
        up, peer, down = vector
        only_up, down_run, peer_run = (
            only_up * up,
            (only_up + down_run) * down,
            peer_run * down + only_up * peer,
        )
    full = only_up + down_run + peer_run
    leaked = best < Fraction(threshold[0], threshold[1])
    return best, full, witness, leaked


# --------------------------------------------------------------------------
# driver
# --------------------------------------------------------------------------
def build_result(raw):
    data = parse_document(raw)
    ixps, rib_records, priors, declared, order_links, query_records = \
        validate_request(data)

    aggregated = aggregate_rib(rib_records, ixps)
    all_links = set()
    for path in aggregated:
        all_links |= path_links(path)

    core_paths, rounds = peel(aggregated)

    core = sorted(set().union(*path_links(p) for p in core_paths)) \
        if core_paths else []
    core_index = {link: position for position, link in enumerate(core)}
    occurrences = collect_occurrences(core_paths, core_index)
    scopes = build_scopes(core_index, occurrences)
    order = check_order(core, order_links, scopes)

    marginals, partition = infer_marginals(core, scopes, occurrences, order)
    if marginals is None:
        return {'error': 'zero-partition'}

    link_records = []
    for link in sorted(all_links):
        if link in marginals:
            probability = marginals[link]
            round_no = 0
        else:
            probability = priors.get(link, UNIFORM)
            round_no = rounds.get(link, 0)
        link_records.append({
            'link': [link[0], link[1]],
            'round': round_no,
            'prob': [float(value) for value in probability],
        })

    query_records_out = []
    for qid, raw_path, num, den in query_records:
        path = normalise(raw_path, ixps)
        answer = {'id': qid, 'path': list(path)}
        if len(set(path)) != len(path):
            answer.update(status='loop', score=None, full=None, witness=None,
                          leaked=None)
        else:
            score, full, witness, leaked = score_query(
                path, (num, den), declared, marginals, priors)
            answer.update(status='ok', score=float(score), full=float(full),
                          witness=witness, leaked=leaked)
        query_records_out.append(answer)

    return {'version': 1, 'links': link_records, 'queries': query_records_out}


def main():
    try:
        raw = sys.stdin.buffer.read()
    except Exception:
        raw = b''
    try:
        result = build_result(raw)
    except Invalid:
        result = {'error': 'invalid'}
    except Exception:
        result = {'error': 'invalid'}
    try:
        text = json.dumps(result, allow_nan=False, separators=(',', ':'))
    except Exception:
        text = '{"error":"invalid"}'
    sys.stdout.write(text)
    sys.stdout.write('\n')
    return 0


if __name__ == '__main__':
    sys.exit(main())
