MAX_INPUT_BYTES = 4194304
MAX_IXPS = 1024
MAX_RIB_RECORDS = 2000
MAX_PRIORS = 2000
MAX_DECLARED = 2000
MAX_QUERIES = 512
MAX_PATH_LEN = 64
