def find_order(core, scopes):
    """Greedy elimination order over the scope graph with width <= 4."""
    if not core:
        return []
    index = {link: i for i, link in enumerate(core)}
    adj = {i: set() for i in range(len(core))}
    for scope in scopes.values():
        for a in scope:
            for b in scope:
                if a != b:
                    adj[a].add(b)
    remaining = set(adj)
    order = []
    width = 0
    while remaining:
        best = None
        for node in sorted(remaining):
            nbrs = adj[node]
            fill = 0
            for a in nbrs:
                for b in nbrs:
                    if a != b and b not in adj[a]:
                        fill += 1
            score = (fill, len(nbrs))
            if best is None or score < best[0]:
                best = (score, node)
        node = best[1]
        nbrs = list(adj[node])
        width = max(width, len(nbrs))
        for a in nbrs:
            for b in nbrs:
                if a != b:
                    adj[a].add(b)
                    adj[b].add(a)
        for a in nbrs:
            adj[a].discard(node)
        del adj[node]
        remaining.discard(node)
        order.append(core[node])
    if width > 4:
        return None
    return order


def scopes_for(doc):
