        expected = reference.run(doc)
        if expected.get('error') == 'zero-partition':
            zero += 1
        raw = json.dumps(doc).encode()
        proc = subprocess.run([sys.executable, '-I', MAIN], input=raw,
                              stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        if proc.returncode != 0:
            print('FAIL(exit) case', n, proc.stderr.decode()[:500])
            print(json.dumps(doc))
            return 1
        try:
            actual = json.loads(proc.stdout)
        except Exception as exc:
            print('FAIL(json) case', n, exc, proc.stdout[:300])
            print(json.dumps(doc))
            return 1
        if not close(expected, actual):
            print('FAIL(mismatch) case', n)
            print('input ', json.dumps(doc))
            print('expect', json.dumps(expected))
            print('actual', json.dumps(actual))
            return 1
    print('ok: %d cases (%d skipped for width, %d zero-partition)' %
          (count - skipped, skipped, zero))
    return 0


if __name__ == '__main__':
    sys.exit(main())
