def check_order(core, order_links, scopes):
    """Validate the elimination order and the promised width."""
    if len(order_links) != len(core):
        raise Invalid('order length')
    seen = set()
    for link in order_links:
        if link in seen:
            raise Invalid('duplicate order entry')
        seen.add(link)
    if seen != set(core):
        raise Invalid('order is not a permutation of the core links')
    index = {link: position for position, link in enumerate(core)}
    adjacency = {position: set() for position in range(len(core))}
    for scope in scopes.values():
        for a in scope:
            for b in scope:
                if a != b:
                    adjacency[a].add(b)
    for link in order_links:
        node = index[link]
        neighbours = adjacency[node]
        if len(neighbours) > MAX_WIDTH:
            raise Invalid('width promise violated')
        group = list(neighbours)
        for a in group:
            for b in group:
                if a != b:
                    adjacency[a].add(b)
                    adjacency[b].add(a)
        for a in group:
            adjacency[a].discard(node)
        del adjacency[node]
    return [index[link] for link in order_links]


def expand_to(src_vars, src_table, dst_vars):
    """Broadcast a factor table onto the variable set dst_vars."""
    position = {var: i for i, var in enumerate(src_vars)}
    source = [0]
    for var in dst_vars:
        slot = position.get(var)
        if slot is None:
            grown = []
            for value in source:
                grown.append(value)
                grown.append(value)
                grown.append(value)
        else:
            stride = 3 ** (len(src_vars) - 1 - slot)
            grown = []
            for value in source:
                base = value - (value // stride % 3) * stride
                grown.append(base)
                grown.append(base + stride)
                grown.append(base + 2 * stride)
        source = grown
    return [src_table[value] for value in source]


def multiply(first, second):
    """Product of two factors over the union of their variables."""
    vars_a, table_a = first
    vars_b, table_b = second
    if vars_a == vars_b:
        return (vars_a, [x * y for x, y in zip(table_a, table_b)])
    union = tuple(sorted(set(vars_a) | set(vars_b)))
    wide = expand_to(vars_a, table_a, union)
    narrow = expand_to(vars_b, table_b, union)
    return (union, [x * y for x, y in zip(wide, narrow)])


def sum_out(factor, variable):
    """Marginalise one variable out of a factor."""
    variables, table = factor
    size = len(variables)
    slot = variables.index(variable)
    stride = 3 ** (size - 1 - slot)
    powers = [1] * (size + 1)
    for i in range(size):
        powers[i + 1] = powers[i] * 3
    result = [0] * powers[size - 1]
    for old in range(powers[size]):
        digit = (old // stride) % 3
        base = old - digit * stride
        new = (base // (3 * stride)) * stride + (base % stride)
        result[new] += table[old]
    keep = variables[:slot] + variables[slot + 1:]
    return (keep, result)


def eliminate(factors, order, skip=None):
    """Bucket elimination; returns the factors left in the pool."""
    pool = list(factors)
    for variable in order:
        if variable == skip:
            continue
        bucket = []
        rest = []
        for factor in pool:
            if variable in factor[0]:
                bucket.append(factor)
            else:
                rest.append(factor)
        if not bucket:
            continue
        combined = bucket[0]
        for factor in bucket[1:]:
            combined = multiply(combined, factor)
        rest.append(sum_out(combined, variable))
        pool = rest
    return pool


def resolve(spec, states, context_pos):
    """Value of a context type under the current assignment."""
    if spec[0] == 0:
        return spec[1]
    state = states[context_pos[spec[1]]]
    return INVERSE[state] if spec[2] else state


def factor_table(scope, edge, items):
    """Tabulated phi_e over the variables of its scope."""
    size = len(scope)
    context = [var for var in scope if var != edge]
    groups = {}
    for count, left, right in items:
        key = (left, right)
        groups[key] = groups.get(key, 0) + count
    context_pos = {var: i for i, var in enumerate(context)}
    slot = scope.index(edge)
    powers = [1] * (size + 1)
    for i in range(size):

    for i in range(size):
        powers[i + 1] = powers[i] * 3
    # weight of every context variable inside the flat table index
    context_weight = []
    position = 0
    for index in range(size):
        if index == slot:
            continue
        context_weight.append(powers[size - 1 - index])
    table = [0] * powers[size]
    context_size = len(context)
    for assignment in range(powers[context_size]):
        states = []
        value = assignment
        for _ in range(context_size):
            states.append(value % 3)
            value //= 3
        base = 0
        for position in range(context_size):
            base += states[position] * context_weight[position]
        for (left, right), count in groups.items():
            left_type = resolve(left, states, context_pos)
            right_type = resolve(right, states, context_pos)
            centre = G_TABLE[left_type][right_type]
            table[base + centre * powers[size - 1 - slot]] += count
    return (tuple(scope), table)


def components(scopes, order):
    """Split the core variables into independent components."""
    parent = {}

    def find(node):
        while parent[node] != node:
            parent[node] = parent[parent[node]]
            node = parent[node]
        return node

    def union(a, b):
        root_a, root_b = find(a), find(b)
        if root_a != root_b:
            parent[root_a] = root_b

    for scope in scopes.values():
        for var in scope:
            if var not in parent:
                parent[var] = var
        first = scope[0]
        for var in scope[1:]:
            union(first, var)
    groups = {}
    for var in parent:
        groups.setdefault(find(var), []).append(var)
    result = []
    for members in groups.values():
        members.sort()
        member_set = set(members)
        local_order = [var for var in order if var in member_set]
        result.append((members, local_order))
    return result


def infer_marginals(core, scopes, occurrences, order):
    """Exact marginals of every core variable and the partition function."""
    factors = []
    for edge in sorted(occurrences):
        factors.append(factor_table(scopes[edge], edge, occurrences[edge]))
    numerators = {}
    partition = 1
    zero_partition = False
    for members, local_order in components(scopes, order):
        member_set = set(members)
        local_factors = [f for f in factors if set(f[0]) <= member_set]
        local_partition = None
        for variable in members:
            pool = eliminate(local_factors, local_order, skip=variable)
            constant = 1
            values = [1, 1, 1]
            for variables, table in pool:
                if not variables:
                    constant *= table[0]
                else:
                    for state in range(3):
                        values[state] *= table[state]
            row = [constant * values[state] for state in range(3)]
            numerators[variable] = row
            total = row[0] + row[1] + row[2]
            if local_partition is None:
                local_partition = total
        if local_partition is None:
            continue
        if local_partition == 0:
            zero_partition = True
        else:
            partition *= local_partition
    if zero_partition or partition == 0:
        return None, 0
    marginals = {}
    for edge, row in numerators.items():
        marginals[core[edge]] = tuple(Fraction(value, partition)
                                      for value in row)
    return marginals, partition


